/// <param name = "_args">main</param>
public static void main(Args        _args)
{
    KCS_KBVBuildingProjectTable     buildingProjectTable;

    update_recordset buildingProjectTable
        setting StatusModified = buildingProjectTable.ModifiedDateTime
        where buildingProjectTable.StatusModified == Global::utcDateTimeNull();
}
